from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.tickers = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_close_prev = None
        self.spy_sma_prev = None

        self.aapl_close_history = RollingWindow[float](5)

        self.lotA_shares = 0
        self.lotB_shares = 0

    def OnData(self, data: Slice):
        for t in self.tickers:
            if not data.ContainsKey(t) or data[t] is None:
                return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        self.aapl_close_history.Add(aapl_close)

        if not self.sma.IsReady or not self.rsi.IsReady or not self.aapl_close_history.IsReady:
            self.spy_close_prev = spy_close
            self.spy_sma_prev = self.sma.Current.Value if self.sma.IsReady else None
            return

        sma_value = self.sma.Current.Value
        rsi_value = self.rsi.Current.Value

        # Sells before buys

        # Strategy A sell
        if self.lotA_shares > 0:
            if self.spy_close_prev is not None and self.spy_sma_prev is not None:
                crossed_below = (self.spy_close_prev >= self.spy_sma_prev) and (spy_close < sma_value)
                if crossed_below:
                    self.MarketOrder(self.spy, -self.lotA_shares)
                    self.lotA_shares = 0

        # Strategy B sell
        if self.lotB_shares > 0:
            if rsi_value > 60:
                self.MarketOrder(self.aapl, -self.lotB_shares)
                self.lotB_shares = 0

        # Strategy A buy
        if self.lotA_shares == 0:
            if self.spy_close_prev is not None and self.spy_sma_prev is not None:
                crossed_above = (self.spy_close_prev <= self.spy_sma_prev) and (spy_close > sma_value)
                if crossed_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.lotA_shares += shares

        # Strategy B buy
        if self.lotB_shares == 0:
            closes = [self.aapl_close_history[i] for i in range(4, -1, -1)]
            red_days = 0
            for i in range(1, 5):
                if closes[i] < closes[i - 1]:
                    red_days += 1
                else:
                    break
            if red_days >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares += shares

        self.spy_close_prev = spy_close
        self.spy_sma_prev = sma_value

