        for s in self.symbols:
            if not data.ContainsKey(s) or data[s] is None:
                return
            if not data.Bars.ContainsKey(s):
                return

        if not self.sma.IsReady or not self.rsi.IsReady:
            self._update_state(data)
            return

        spy_close = data.Bars[self.spy].Close
        spy_sma = self.sma.Current.Value

        aapl_close = data.Bars[self.aapl].Close

        # ---- Sells first ----

        # Strategy A sell
        if self.strategyA_shares > 0:
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                crossed_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < spy_sma)
                if crossed_below:
                    self.MarketOrder(self.spy, -self.strategyA_shares)
                    self.strategyA_shares = 0

        # Strategy B sell
        if self.strategyB_shares > 0:
            rsi_val = self.rsi.Current.Value
            if rsi_val > 60:
                self.MarketOrder(self.aapl, -self.strategyB_shares)
                self.strategyB_shares = 0

        # ---- Buys ----

        # Strategy A buy
        if self.strategyA_shares == 0:
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                crossed_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > spy_sma)
                if crossed_above:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = 0.40 * portfolio_value
                    shares = int(invest_amount // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.strategyA_shares = shares

        # Strategy B buy
        if self.strategyB_shares == 0:
            if self.aapl_red_streak >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    shares = int(20000 // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.strategyB_shares = shares

        self._update_state(data)

    def _update_state(self, data: Slice):
        if data.Bars.ContainsKey(self.spy):
            spy_close = data.Bars[self.spy].Close
            spy_sma_ready = self.sma.IsReady
            self.spy_prev_close = spy_close
            self.spy_prev_sma = self.sma.Current.Value if spy_sma_ready else None

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = data.Bars[self.aapl].Close
            prev = self.prev_close.get(self.aapl)
            if prev is not None:
                if aapl_close < prev:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.prev_close[self.aapl] = aapl_close

        for s in self.symbols:
            if data.Bars.ContainsKey(s) and s != self.aapl:
                self.prev_close[s] = data.Bars[s].Close

