from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in self.tickers:
            equity = self.AddEquity(t, Resolution.Daily)
            self.symbols[t] = equity.Symbol

        self.spy_symbol = self.symbols["SPY"]
        self.aapl_symbol = self.symbols["AAPL"]

        # Indicators
        self.spy_sma = self.SMA(self.spy_symbol, 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl_symbol, 14, Resolution.Daily)

        # Cross-detection state
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Red-streak state for AAPL
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # Private lots
        self.lot_a_shares = 0  # Strategy A (SPY)
        self.lot_b_shares = 0  # Strategy B (AAPL)

    def OnData(self, data: Slice):
        # Skip the day entirely if any subscribed ticker's bar is missing
        for t in self.tickers:
            sym = self.symbols[t]
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy_symbol].Close
        aapl_close = data.Bars[self.aapl_symbol].Close

        # Update AAPL red-streak (market-state, computed continuously)
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Require indicators to be fully formed before trading
        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady

        if indicators_ready and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            spy_sma_today = self.spy_sma.Current.Value

            crosses_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_today)
            crosses_below = (self.prev_spy_close > self.prev_spy_sma) and (spy_close <= spy_sma_today)

            # ---- Slot 1: Strategy A (SPY) ----
            # Sell before buy
            if self.lot_a_shares > 0:
                if crosses_below:
                    self.MarketOrder(self.spy_symbol, -self.lot_a_shares)
                    self.lot_a_shares = 0
            else:
                if crosses_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = int(target_value // spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy_symbol, qty)
                        self.lot_a_shares = qty

        # ---- Slot 2: Strategy B (AAPL) ----
        if self.aapl_rsi.IsReady:
            rsi_value = self.aapl_rsi.Current.Value

            # Sell before buy
            if self.lot_b_shares > 0:
                if rsi_value > 60:
                    self.MarketOrder(self.aapl_symbol, -self.lot_b_shares)
                    self.lot_b_shares = 0
            else:
                if self.aapl_red_streak >= 3:
                    cash_available = self.Portfolio.Cash
                    if cash_available >= 20000:
                        qty = int(20000 // aapl_close)
                        if qty > 0:
                            self.MarketOrder(self.aapl_symbol, qty)
                            self.lot_b_shares = qty

        # Update previous-value state for next bar
        self.prev_spy_close = spy_close
        if self.spy_sma.IsReady:
            self.prev_spy_sma = self.spy_sma.Current.Value
        self.prev_aapl_close = aapl_close

