class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Slot 1 - Strategy A (SPY, SMA cross)
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.lotA_shares = 0

        # Slot 2 - Strategy B (AAPL, red streak / RSI)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)
        self.aapl_prev_close = None
        self.aapl_red_streak = 0
        self.lotB_shares = 0

    def OnData(self, data):
        # Skip all rule evaluation if any subscribed ticker's bar is missing today
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol) or data.Bars[symbol] is None:
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # ---------------- Slot 1: Strategy A (SPY) ----------------
        if self.spy_sma.IsReady:
            current_sma = self.spy_sma.Current.Value
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                crossed_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > current_sma)
                crossed_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < current_sma)

                if self.lotA_shares > 0:
                    if crossed_below:
                        self.MarketOrder(self.spy, -self.lotA_shares)
                        self.lotA_shares = 0
                elif self.lotA_shares == 0:
                    if crossed_above:
                        target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                        shares = math.floor(target_value / spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.lotA_shares = shares

            self.spy_prev_close = spy_close
            self.spy_prev_sma = current_sma

        # ---------------- Slot 2: Strategy B (AAPL) ----------------
        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_prev_close = aapl_close

        if self.lotB_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lotB_shares)
                self.lotB_shares = 0
        elif self.lotB_shares == 0:
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = math.floor(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares = shares

