class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            equity = self.AddEquity(t, Resolution.Daily)
            equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
            self.symbols[t] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 50
        self.sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)

        self.rsi_period = 14
        self.rsi = self.RSI(self.aapl, self.rsi_period, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A state (SPY)
        self.a_shares = 0
        self.a_prev_close = None
        self.a_prev_sma = None

        # Strategy B state (AAPL)
        self.b_shares = 0
        self.aapl_close_history = []  # store recent closes for red-day streak
        self.b_prev_rsi_above60 = False

        self.warmup_bars = max(self.sma_period, self.rsi_period) + 5
        self.SetWarmUp(self.warmup_bars, Resolution.Daily)

    def OnData(self, data: Slice):
        # Check all subscribed tickers have data today
        for sym in self.symbols.values():
            if not data.ContainsKey(sym) or data[sym] is None:
                return

        if self.IsWarmingUp:
            self._update_streak(data)
            return

        if not self.sma.IsReady or not self.rsi.IsReady:
            self._update_streak(data)
            return

        spy_bar = data[self.spy]
        aapl_bar = data[self.aapl]

        spy_close = spy_bar.Close
        sma_value = self.sma.Current.Value

        # Update AAPL close history for streak detection BEFORE evaluating (need previous closes)
        self._update_streak(data)

        # ---------- Strategy A: SPY ----------
        if self.a_prev_close is not None and self.a_prev_sma is not None:
            crossed_below = (self.a_prev_close >= self.a_prev_sma) and (spy_close < sma_value)
            crossed_above = (self.a_prev_close <= self.a_prev_sma) and (spy_close > sma_value)

            # Sell before buy
            if self.a_shares > 0:
                if crossed_below:
                    self.MarketOrder(self.spy, -self.a_shares)
                    self.a_shares = 0
            else:
                if crossed_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = int(math.floor(target_value / spy_close))
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)
                        self.a_shares = qty

        self.a_prev_close = spy_close
        self.a_prev_sma = sma_value

        # ---------- Strategy B: AAPL ----------
        aapl_close = aapl_bar.Close
        rsi_value = self.rsi.Current.Value

        # Sell before buy
        if self.b_shares > 0:
            if rsi_value > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0
        else:
            if self._is_red_streak(3):
                cash_available = self.Portfolio.Cash
                cost_target = 20000.0
                if cash_available >= cost_target:
                    qty = int(math.floor(cost_target / aapl_close))
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.b_shares = qty

    def _update_streak(self, data: Slice):
        aapl_bar = data[self.aapl]
        if aapl_bar is None:
            return
        self.aapl_close_history.append(aapl_bar.Close)
        if len(self.aapl_close_history) > 10:
            self.aapl_close_history = self.aapl_close_history[-10:]

    def _is_red_streak(self, n):
        hist = self.aapl_close_history
        if len(hist) < n + 1:
            return False
        count = 0
        for i in range(len(hist) - 1, 0, -1):
            if hist[i] < hist[i - 1]:
                count += 1
                if count >= n:
                    return True
            else:
                break
        return count >= n

