        self.aapl = self.symbols["AAPL"]

        self.sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A state
        self.a_lot_shares = 0
        self.a_prev_close_above = None  # None until we have both close and sma

        # Strategy B state
        self.b_lot_shares = 0
        self.aapl_close_history = RollingWindow[float](5)
        self.b_prev_rsi_above = None

        self.prev_closes = {}  # ticker -> previous day's close
        self.consecutive_red = {"AAPL": 0}

    def OnData(self, data: Slice):
        for t in self.tickers:
            sym = self.symbols[t]
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close
        aapl_open = data.Bars[self.aapl].Open

        # Update AAPL consecutive red-day tracking
        prev_aapl_close = self.prev_closes.get("AAPL", None)
        if prev_aapl_close is not None:
            if aapl_close < prev_aapl_close:
                self.consecutive_red["AAPL"] += 1
            else:
                self.consecutive_red["AAPL"] = 0

        # ---- Strategy A: SPY SMA cross ----
        if self.sma.IsReady:
            sma_val = self.sma.Current.Value
            a_above_today = spy_close > sma_val

            if self.a_prev_close_above is not None:
                cross_above = (not self.a_prev_close_above) and a_above_today
                cross_below = self.a_prev_close_above and (not a_above_today)

                # sell before buy
                if self.a_lot_shares > 0 and cross_below:
                    self.MarketOrder(self.spy, -self.a_lot_shares)
                    self.a_lot_shares = 0

                if self.a_lot_shares == 0 and cross_above:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    target_value = 0.40 * portfolio_value
                    shares = int(target_value // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.a_lot_shares += shares

            self.a_prev_close_above = a_above_today

        # ---- Strategy B: AAPL red streak / RSI ----
        # sell before buy
        if self.b_lot_shares > 0 and self.rsi.IsReady:
            rsi_above_60_today = self.rsi.Current.Value > 60
            if self.b_prev_rsi_above is None:
                self.b_prev_rsi_above = rsi_above_60_today
            else:
                if rsi_above_60_today and self.b_lot_shares > 0:
                    self.MarketOrder(self.aapl, -self.b_lot_shares)
                    self.b_lot_shares = 0
                self.b_prev_rsi_above = rsi_above_60_today
        elif self.rsi.IsReady:
            # keep tracking prev state even if flat, for correctness of "closes above" semantics
            self.b_prev_rsi_above = self.rsi.Current.Value > 60

        if self.b_lot_shares == 0:
            if self.consecutive_red.get("AAPL", 0) >= 3:
                cash_available = self.Portfolio.Cash
                cost = 20000.0
                if cash_available >= cost:
                    shares = int(cost // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.b_lot_shares += shares

        # update previous closes
        for t in self.tickers:
            sym = self.symbols[t]
            self.prev_closes[t] = data.Bars[sym].Close

