class ParallelStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in self.tickers:
            equity = self.AddEquity(t, Resolution.Daily)
            equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
            self.symbols[t] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wintersor if False else MovingAverageType.Wilders, Resolution.Daily)

        self.spy_close_prev = None
        self.spy_sma_prev = None

        self.aapl_close_history = RollingWindow[float](5)

        self.aapl_prev_close = None
        self.aapl_consecutive_red = 0

        self.rsi_prev_above_60 = False

        self.lotA_shares = 0
        self.lotB_shares = 0

        self.warmup_bars_spy = 0
        self.warmup_bars_aapl = 0

    def OnData(self, data: Slice):
        for t in self.tickers:
            sym = self.symbols[t]
            if not data.ContainsKey(sym) or data[sym] is None:
                return
            if not data.Bars.ContainsKey(sym):
                return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_close = spy_bar.Close

        aapl_close = aapl_bar.Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_consecutive_red += 1
            else:
                self.aapl_consecutive_red = 0

        sma_ready = self.sma100.IsReady
        rsi_ready = self.rsi14.IsReady

        sma_val = self.sma100.Current.Value if sma_ready else None
        rsi_val = self.rsi14.Current.Value if rsi_ready else None

        # Strategy A - Sell first
        if self.lotA_shares > 0:
            if sma_ready and self.spy_close_prev is not None and self.spy_sma_prev is not None:
                crossed_below = (self.spy_close_prev >= self.spy_sma_prev) and (spy_close < sma_val)
                if crossed_below:
                    self.Liquidate(self.spy)
                    self.lotA_shares = 0
        else:
            if sma_ready and self.spy_close_prev is not None and self.spy_sma_prev is not None:
                crossed_above = (self.spy_close_prev <= self.spy_sma_prev) and (spy_close > sma_val)
                if crossed_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.lotA_shares = shares

        # Strategy B - Sell first
        if self.lotB_shares > 0:
            if rsi_ready and rsi_val > 60:
                self.Liquidate(self.aapl)
                self.lotB_shares = 0
        else:
            if self.aapl_consecutive_red >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    shares = int(20000 // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares = shares

        # Update previous values for next bar's cross detection
        if sma_ready:
            self.spy_close_prev = spy_close
            self.spy_sma_prev = sma_val

        self.aapl_prev_close = aapl_close

