from AlgorithmImports import *

class TwoSlotStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_close_history = []
        self.prev_rsi = None

        self.lotA_shares = 0
        self.lotB_shares = 0

        self.aapl_red_streak = 0

    def OnData(self, data):
        for ticker in self.tickers:
            symbol = self.symbols[ticker]
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        if not self.sma100.IsReady or not self.rsi14.IsReady:
            self._update_state(data)
            return

        spy_close = float(data[self.spy].Close)
        sma_value = float(self.sma100.Current.Value)
        aapl_close = float(data[self.aapl].Close)
        rsi_value = float(self.rsi14.Current.Value)

        if self.prev_spy_close is None or self.prev_spy_sma is None or self.prev_aapl_close is None or self.prev_rsi is None:
            self._update_state(data)
            return

        # ---- Slot 2: Strategy B (AAPL) - sell before buy ----
        if self.lotB_shares > 0:
            crosses_above_60 = (self.prev_rsi <= 60) and (rsi_value > 60)
            if crosses_above_60:
                self.MarketOrder(self.aapl, -self.lotB_shares)
                self.lotB_shares = 0

        if self.lotB_shares == 0:
            if self.aapl_red_streak >= 3:
                cost = 20000.0
                if self.Portfolio.Cash >= cost:
                    shares = int(cost // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares += shares

        # ---- Slot 1: Strategy A (SPY) - sell before buy ----
        if self.lotA_shares > 0:
            crosses_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < sma_value)
            if crosses_below:
                self.MarketOrder(self.spy, -self.lotA_shares)
                self.lotA_shares = 0

        if self.lotA_shares == 0:
            crosses_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > sma_value)
            if crosses_above:
                target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
                shares = int(target_value // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lotA_shares += shares

        self._update_state(data)

    def _update_state(self, data):
        spy_close = float(data[self.spy].Close)
        aapl_close = float(data[self.aapl].Close)

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.prev_spy_close = spy_close
        self.prev_aapl_close = aapl_close

        if self.sma100.IsReady:
            self.prev_spy_sma = float(self.sma100.Current.Value)
        if self.rsi14.IsReady:
            self.prev_rsi = float(self.rsi14.Current.Value)

