from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        self.prev_rsi = None

        # Strategy A (SPY) lot state
        self.a_shares = 0

        # Strategy B (AAPL) lot state
        self.b_shares = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):

        if self.IsWarmingUp:
            return

        for symbol in self.symbols:
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return
            if not data.Bars.ContainsKey(symbol):
                return

        if not self.sma100.IsReady or not self.rsi14.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        sma_value = self.sma100.Current.Value
        rsi_value = self.rsi14.Current.Value

        # Update AAPL red streak (market-state, computed continuously)
        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Determine crosses for SPY vs SMA100
        crossed_above = False
        crossed_below = False
        if self.prev_spy_close is not None and self.prev_spy_sma is not None:
            if self.prev_spy_close <= self.prev_spy_sma and spy_close > sma_value:
                crossed_above = True
            if self.prev_spy_close >= self.prev_spy_sma and spy_close < sma_value:
                crossed_below = True

        # ---- Strategy A: sells before buys ----
        if self.a_shares > 0:
            if crossed_below:
                self.MarketOrder(self.spy, -self.a_shares)
                self.a_shares = 0

        if self.a_shares == 0:
            if crossed_above:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                qty = int(np.floor(target_value / spy_close)) if spy_close > 0 else 0
                if qty > 0:
                    self.MarketOrder(self.spy, qty)
                    self.a_shares = qty

        # ---- Strategy B: sells before buys ----
        if self.b_shares > 0:
            if rsi_value > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0

        if self.b_shares == 0:
            if self.aapl_red_streak >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    qty = int(np.floor(20000 / aapl_close)) if aapl_close > 0 else 0
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.b_shares = qty

        # Update previous-day state trackers
        self.prev_spy_close = spy_close
        self.prev_spy_sma = sma_value
        self.aapl_prev_close = aapl_close

